\newcommand{\R}{\mathbb{R}}
\newcommand{\relu}{\operatorname{ReLU}}
\newcommand{\ind}{\mathbf{1}}

\title{Feasible Activation Cells and Exact Affine Semantics\\of Shallow ReLU Networks}
\author{Aristotle}
\date{July 28, 2026}

\begin{document}
\maketitle

\begin{abstract}
A scalar-output, one-hidden-layer rectified linear unit network is globally nonlinear but locally governed by finitely many affine formulas. For $k$ hidden neurons acting on $\R^n$, a Boolean pattern prescribes a mixed system of strict and weak affine inequalities: active neurons require positive preactivation, while inactive neurons require nonpositive preactivation. We prove that the activation cell of a pattern is nonempty exactly when this inequality system is feasible. For every pattern we define an explicit selected affine formula and prove that the network output equals it throughout the corresponding cell. We prove that the selected formula preserves arbitrary affine combinations and deduce the same identity for the network whenever the relevant points remain in one cell. The cells are convex, making this condition automatic for interpolation between two points in a common cell. Algorithms for pattern evaluation, feasibility testing, and extraction of local affine coefficients are given, together with applications to interpretation, robustness, optimization, and exact regional analysis.
\end{abstract}

\section{Introduction}

The rectified linear unit is the scalar function
\[
\relu(z)=\max\{z,0\}.
\]
It has two branches: the identity on positive inputs and zero on nonpositive inputs. A collection of such gates creates rich global behavior because each hidden neuron selects a branch and the joint selection depends on the input.

For a shallow network, every branch condition is an affine inequality in the original input. A joint branch selection therefore describes an intersection of half-spaces. On that intersection every gate can be replaced by its selected branch, leaving an affine expression. Several qualifications are essential. Not all $2^k$ formal patterns need occur; strict positivity must be distinguished from nonnegativity at boundaries; and activation cells need not be maximal regions on which the total output happens to be affine.

We establish, without genericity assumptions, four central statements. First, a pattern is feasible precisely when its mixed strict/weak inequality system has a solution. Second, the network equals an explicitly selected affine formula on the corresponding cell. Third, that formula preserves arbitrary affine combinations. Fourth, the network obeys the same law when the points involved remain in one cell.

\section{Model and definitions}

Let $n,k\in\mathbb{N}$ and let $x=(x_1,\dots,x_n)\in\R^n$. For neuron $j\in\{1,\dots,k\}$, let $w_j=(w_{j1},\dots,w_{jn})\in\R^n$ and $b_j\in\R$.

\begin{definition}[Affine preactivation]
The preactivation of neuron $j$ is
\[
z_j(x)=w_j\cdot x+b_j=\sum_{i=1}^n w_{ji}x_i+b_j.
\]
\end{definition}

\begin{definition}[Activation pattern]
The pattern of $x$ is $p(x)\in\{0,1\}^k$, where
\[
p_j(x)=\begin{cases}1,&z_j(x)>0,\\0,&z_j(x)\le 0.\end{cases}
\]
Thus a zero preactivation belongs to the inactive branch.
\end{definition}

\begin{definition}[Activation cell and feasibility]
For $p\in\{0,1\}^k$, define
\[
C_p=\{x\in\R^n:p(x)=p\}.
\]
The pattern $p$ is \emph{feasible} when $C_p\ne\varnothing$.
\end{definition}

The nonempty cells partition $\R^n$: every input has exactly one pattern. Empty cells represent formal bit vectors incompatible with the geometry.

\begin{definition}[Pattern inequality system]
For $p\in\{0,1\}^k$, let $\mathcal I_p(x)$ denote
\[
\begin{cases}
z_j(x)>0,&p_j=1,\\z_j(x)\le0,&p_j=0,
\end{cases}
\qquad j=1,\dots,k.
\]
\end{definition}

Let $v=(v_1,\dots,v_k)\in\R^k$ and $c\in\R$.

\begin{definition}[Network output]
The scalar output is
\[
F(x)=\sum_{j=1}^k v_j\relu(z_j(x))+c.
\]
\end{definition}

\begin{definition}[Selected affine formula]
For $p\in\{0,1\}^k$, define
\[
A_p(x)=\sum_{j=1}^k
\begin{cases}v_jz_j(x),&p_j=1,\\0,&p_j=0,\end{cases}+c.
\]
Writing $S_p=\{j:p_j=1\}$, this becomes
\[
A_p(x)=g_p\cdot x+d_p,
\quad
g_p=\sum_{j\in S_p}v_jw_j,
\quad
d_p=c+\sum_{j\in S_p}v_jb_j.
\]
\end{definition}

\section{Feasibility and cell geometry}

\begin{theorem}[Activation-cell feasibility]
For every $p\in\{0,1\}^k$,
\[
C_p\ne\varnothing
\quad\Longleftrightarrow\quad
\exists x\in\R^n\ \forall j,
\begin{cases}z_j(x)>0,&p_j=1,\\z_j(x)\le0,&p_j=0.\end{cases}
\]
\end{theorem}

\begin{proof}
If $x\in C_p$, then $p(x)=p$ coordinatewise. The definition of each activation bit gives the requested strict or weak inequality. Conversely, if $x$ satisfies every prescribed inequality, the activation test in coordinate $j$ returns $p_j$ for every $j$. Hence $p(x)=p$ and $x\in C_p$.
\end{proof}

\begin{proposition}[Half-space representation and convexity]
For every pattern $p$,
\[
C_p=
\bigcap_{j:p_j=1}\{x:z_j(x)>0\}
\cap
\bigcap_{j:p_j=0}\{x:z_j(x)\le0\}.
\]
Consequently $C_p$ is convex, though it need be neither open nor closed.
\end{proposition}

\begin{proof}
The equality expands $p(x)=p$ coordinatewise. Each constituent is an affine half-space and is convex; intersections of convex sets are convex. The mixture of strict and weak inequalities accounts for the possible failure of openness and closedness.
\end{proof}

Indeed, if $x,y\in C_p$ and $0\le t\le1$, then
\[
z_j(tx+(1-t)y)=tz_j(x)+(1-t)z_j(y).
\]
Positivity is preserved for active coordinates and nonpositivity for inactive coordinates, so the segment remains in $C_p$.

\begin{remark}[Feasible versus formal patterns]
There are $2^k$ formal patterns, hence at most $2^k$ feasible cells, but equality need not hold. In one dimension, $z_1(x)=x+1$ and $z_2(x)=-x+2$ make $(0,0)$ impossible because it requires both $x\le-1$ and $x\ge2$.
\end{remark}

\section{Exact affine semantics}

\begin{theorem}[Cellwise affine representation]
For every $p\in\{0,1\}^k$ and $x\in C_p$,
\[
F(x)=A_p(x)=g_p\cdot x+d_p.
\]
\end{theorem}

\begin{proof}
If $p_j=1$, then $z_j(x)>0$ and $\relu(z_j(x))=z_j(x)$. If $p_j=0$, then $z_j(x)\le0$ and $\relu(z_j(x))=0$. Thus every network summand equals its selected counterpart. Summing and adding $c$ proves $F(x)=A_p(x)$. Expanding active preactivations and collecting coefficients gives $g_p\cdot x+d_p$.
\end{proof}

\begin{corollary}[Exact local slope]
On a nonempty cell $C_p$, the network has constant affine slope
\[
g_p=\sum_{j:p_j=1}v_jw_j.
\]
At every interior point of the cell, $F$ is differentiable with gradient $g_p$.
\end{corollary}

\begin{proof}
The network agrees with $x\mapsto g_p\cdot x+d_p$ on the cell. An interior point has a neighborhood on which this agreement holds, and differentiation yields the claim.
\end{proof}

\begin{remark}[Cells and maximal affine regions]
Activation cells are a canonical branch partition but need not be maximal affine regions of $F$. If $v_j=0$, switching neuron $j$ changes the pattern without changing the output. Different active sets may also produce the same slope and intercept through cancellation.
\end{remark}

\section{Affine combinations}

\begin{theorem}[Affinity of the selected formula]
For every pattern $p$, every $x,y\in\R^n$, and every $t\in\R$,
\[
A_p(tx+(1-t)y)=tA_p(x)+(1-t)A_p(y).
\]
\end{theorem}

\begin{proof}
Every preactivation satisfies
\[
z_j(tx+(1-t)y)=tz_j(x)+(1-t)z_j(y).
\]
For fixed $p$, retaining or discarding the $j$th term is independent of the input. Multiplication by $v_j$ and summation preserve the identity, while $tc+(1-t)c=c$. Equivalently, substitute $A_p(u)=g_p\cdot u+d_p$ and distribute.
\end{proof}

\begin{theorem}[Network affinity within a cell]
Let $p\in\{0,1\}^k$, $x,y\in\R^n$, and $t\in\R$. If
\[
x\in C_p,\qquad y\in C_p,\qquad tx+(1-t)y\in C_p,
\]
then
\[
F(tx+(1-t)y)=tF(x)+(1-t)F(y).
\]
\end{theorem}

\begin{proof}
Use the cellwise representation at all three points to replace $F$ by $A_p$, then apply the affinity of $A_p$.
\end{proof}

\begin{corollary}[Exact interpolation]
If $x,y\in C_p$ and $0\le t\le1$, then
\[
F(tx+(1-t)y)=tF(x)+(1-t)F(y).
\]
\end{corollary}

\begin{proof}
Convexity keeps the interpolated point in $C_p$, so the preceding theorem applies.
\end{proof}

For extrapolation, the third membership condition is essential because the affine path may cross a switching hyperplane.

\section{Boundaries and continuity}

The strict-positive convention assigns $z_j(x)=0$ to the inactive branch. This changes the label at a boundary but not the network value, since $\relu(0)=0$. If adjacent patterns differ in coordinate $j$, their selected formulas differ by $v_jz_j(x)$, which vanishes on the hyperplane $z_j(x)=0$. Multiple simultaneous switches behave similarly. Thus shallow ReLU networks are continuous across cell boundaries, though their gradients may jump by sums of vectors $v_jw_j$.

Strict feasibility can be tested using a margin variable. For patterns having at least one active coordinate, solve
\[
\max\ \delta
\]
subject to
\[
z_j(x)\ge\delta\quad(p_j=1),
\qquad z_j(x)\le0\quad(p_j=0),
\qquad \delta\le1.
\]
The original mixed system is feasible exactly when the optimum is positive. If there are no active coordinates, ordinary weak feasibility suffices.

\section{Algorithms and complexity}

\subsection{Pattern evaluation}
Compute $z=Wx+b$ and return $p_j=1$ exactly when $z_j>0$. Dense evaluation costs $O(kn)$ arithmetic operations and $O(k)$ additional storage.

\subsection{Selected coefficient extraction}
Initialize $g=0\in\R^n$ and $d=c$. For each active $j$, update
\[
g\leftarrow g+v_jw_j,
\qquad d\leftarrow d+v_jb_j.
\]
Then $g\cdot x+d$ equals the network throughout $C_p$. Dense worst-case time is $O(kn)$ and additional storage is $O(n)$; sparsity and a small active set reduce the cost.

\subsection{Feasibility testing}
Construct the $k$ pattern inequalities and solve the strict-feasibility problem, for instance with the margin formulation. Standard linear-programming methods apply. Testing all formal patterns has a worst-case factor $2^k$, although arrangement traversal and adjacency searches may avoid many impossible candidates.

\subsection{Numerical identity checks}
For an input $x$, compute $F(x)$ and $A_{p(x)}(x)$. For points sharing a pattern, sample $t\in[0,1]$ and compare $F(tx+(1-t)y)$ with $tF(x)+(1-t)F(y)$. These calculations illustrate exact identities but floating-point software should report margins near boundaries.

\section{Examples}

\begin{example}[A one-dimensional three-piece network]
Let
\[
z_1(x)=x+1,\qquad z_2(x)=-x+2,
\]
with $v_1=2$, $v_2=-1$, and $c=\tfrac12$. Then
\[
F(x)=2\relu(x+1)-\relu(-x+2)+\tfrac12.
\]
On $x\le-1$, the selected formula is $x-\tfrac32$. On $-1<x<2$, it is $3x+\tfrac12$. On $x>2$, it is $2x+\tfrac52$. Adjacent formulas agree at $x=-1$ and $x=2$, while slopes change from $1$ to $3$ to $2$. The pattern $(0,0)$ is infeasible.
\end{example}

\begin{example}[Two-dimensional coefficients]
Let
\[
w_1=(1,1),\ b_1=-1,
\qquad w_2=(-1,2),\ b_2=0,
\]
with $v_1=3$, $v_2=-2$, and $c=1$. For $p=(1,0)$,
\[
g_p=(3,3),\qquad d_p=-2.
\]
Thus $F(x_1,x_2)=3x_1+3x_2-2$ throughout
\[
x_1+x_2-1>0,
\qquad -x_1+2x_2\le0.
\]
Every segment joining two points in this cell carries exact linear interpolation of output values.
\end{example}

\section{Applications}

\paragraph{Exact local interpretation.}
At an input $x$, the pattern $p(x)$ determines $(g_p,d_p)$. The equation $F(u)=g_p\cdot u+d_p$ is exact for every $u$ in the same cell, rather than merely a first-order approximation.

\paragraph{Robustness.}
For a norm with dual norm $\|\cdot\|_*$, the distance from $x$ to the hyperplane $z_j=0$ is controlled by
\[
\frac{|z_j(x)|}{\|w_j\|_*}
\]
when $w_j\ne0$. Perturbations that do not reach any switching hyperplane preserve both the affine formula and its explanation.

\paragraph{Regional optimization.}
On a fixed cell, optimizing the output means optimizing an affine function subject to affine inequalities. Linear side constraints produce linear programs, and quadratic penalties produce quadratic programs. Global analysis separates into a combinatorial search over feasible patterns and tractable within-cell problems.

\paragraph{Verification and reachability.}
An output bound over a domain can be established by intersecting the domain with relevant cells and optimizing each selected formula. Empty intersections are discarded by feasibility testing.

\paragraph{Geometry-aware compression.}
If neighboring feasible patterns select identical $(g_p,d_p)$, their cells may be merged when representing the output function. This distinguishes activation-level complexity from function-level complexity.

\section{Limitations and future work}

No general-position, nondegeneracy, or nonzero-weight assumptions have been made. Consequently, the number of feasible patterns may be much smaller than $2^k$, and activation cells need not equal maximal affine regions.

The present analysis treats one hidden layer. In deeper networks, later preactivations are piecewise affine rather than globally affine in the original input. The branch-freezing idea persists, but the geometry must be developed inductively relative to earlier-layer cells.

Natural next steps are:
\begin{enumerate}[label=\arabic*.]
\item generalize the scalar-output theorem to vector-valued output layers;
\item package each selected formula as an affine map and prove continuity across adjacent cell boundaries;
\item impose explicit genericity assumptions relating feasible cells to maximal linear regions;
\item establish sharper hyperplane-arrangement region bounds in fixed input dimension; and
\item extend the argument inductively to deep ReLU networks.
\end{enumerate}
Further computational work may develop output-sensitive cell enumeration, adjacency graphs, and certified margin calculations.

\section{Conclusion}

A shallow ReLU network has an exact discrete-geometric semantics. A Boolean pattern specifies strict and weak affine inequalities, and its cell is nonempty exactly when those inequalities are feasible. Fixing a feasible pattern replaces every gate by a known branch and yields an explicit affine formula. That formula preserves arbitrary affine combinations, and so does the network whenever the relevant points remain in one cell. Convexity guarantees this behavior for interpolation between points in a common cell.

The arithmetic within each cell is elementary; the global nonlinearity lies in the geometric mosaic that chooses among the affine formulas. This separation supports exact interpretation, robustness analysis, optimization, and verification while making clear which stronger claims require additional assumptions.

\end{document}

