from typing import Sequence

def selected_affine(weights: Sequence[Sequence[float]], biases: Sequence[float], output_weights: Sequence[float], output_bias: float, pattern: Sequence[bool]) -> tuple[tuple[float,...],float]:
    n=len(weights[0]) if weights else 0
    g=[0.0]*n; d=output_bias
    for active,row,b,v in zip(pattern,weights,biases,output_weights):
        if active:
            g=[gi+v*wij for gi,wij in zip(g,row)]; d+=v*b
    return tuple(g),d

from itertools import product
from typing import Callable, Sequence

def feasible_patterns_by_witness(k: int, candidates: Sequence[tuple[float,...]], pattern_at: Callable[[tuple[float,...]], tuple[bool,...]]) -> dict[tuple[bool,...],tuple[float,...]]:
    witnesses={}
    for x in candidates: witnesses.setdefault(pattern_at(x),x)
    return {p:witnesses[p] for p in product((False,True),repeat=k) if p in witnesses}

